const FALLBACK_FAQ=[{"id":1,"category":"신청","q":"2027년 수산자원보호 직불제 신청기간은 언제인가요?","a":"2027년 사업의 신청·접수 기간은 2026년 11월 16일부터 12월 11일까지입니다. 신청단체의 지역을 관할하는 시·군·구에 신청서류를 제출합니다.","keywords":["신청기간","11월16일","12월11일"],"source":"2027 사업 시행지침"},{"id":2,"category":"단체구성","q":"2027년 단체 구성 최소 어선 수는 몇 척인가요?","a":"2027 시행자료는 근해어업 5척 이상, 연안어업(구획어업 포함) 10척 이상으로 신청단체를 구성하도록 안내합니다.","keywords":["근해5","연안10","최소척수"],"source":"2027 사업 시행지침·준수의무 가이드라인"},{"id":3,"category":"단체구성","q":"근해와 연안을 같이 단체로 구성할 수 있나요?","a":"아니요. 근해어업과 연안어업은 혼합하여 단체를 구성할 수 없습니다.","keywords":["근해","연안","혼합"],"source":"2027 준수의무 가이드라인"},{"id":4,"category":"신청","q":"준수의무 이행계획 기간은 언제인가요?","a":"준수의무 이행계획은 2027년 1월 1일부터 9월 30일까지의 기간 안에서 설정합니다.","keywords":["이행기간","1월1일","9월30일"],"source":"2027 사업 시행지침·준수의무 가이드라인"},{"id":5,"category":"신청","q":"기본의무와 선택의무는 어떻게 구성되나요?","a":"기본의무는 총허용어획량(TAC) 준수이며, 2개 이상의 선택의무를 신청해야 합니다. 2027 자료의 선택의무는 일시적·자율적 조업중단, 어획증명(전자어획보고), 그 밖의 의무입니다.","keywords":["기본의무","선택의무","2개"],"source":"2027 사업 시행지침·준수의무 가이드라인"},{"id":6,"category":"신청","q":"선택의무 참여율 기준은 어떻게 되나요?","a":"기본의무는 구성원 전원이 참여해야 합니다. 선택의무는 원칙적으로 구성원의 80% 이상이 참여해야 하며, 어획증명(전자어획보고)은 50% 이상 참여 시 인정됩니다.","keywords":["참여율","80%","50%"],"source":"2027 준수의무 가이드라인"},{"id":7,"category":"신청","q":"2027년 조업일수 요건은 몇 일인가요?","a":"조업일수 산정기간(2026.10.1.~2027.9.30.) 내 원칙적으로 60일 이상이어야 합니다. 시행계획 3단계(정착) 대상 중 어선별 TAC가 설정된 어종을 주로 조업하는 어선으로 구성된 신청단체는 30일 이상이면 인정됩니다.","keywords":["조업일수","60일","30일","TAC3단계"],"source":"2027 사업 시행지침"},{"id":8,"category":"TAC","q":"2027년 TAC 기본의무 배점은 몇 점인가요?","a":"총허용어획량(TAC) 준수 기본의무는 최대 35점입니다. TAC 어종 수 또는 TAC 관리비율에 따라 35·30·25·20·15점으로 평가됩니다.","keywords":["TAC","35점","관리비율"],"source":"2027 준수의무 가이드라인"},{"id":9,"category":"TAC","q":"시·도관리 연안 TAC 시범은 평가에서 어떻게 인정되나요?","a":"여러 어종이나 TAC 관리비율과 관계없이 1개 어종을 적용하는 것으로 인정합니다.","keywords":["시범TAC","1개어종"],"source":"2027 준수의무 가이드라인"},{"id":10,"category":"휴어","q":"2027년 조업중단(휴어)은 최소 며칠이어야 하나요?","a":"2027년 1월 1일부터 9월 30일 사이에 연속하는 날짜 15일 이상을 설정해야 합니다. 조업중단 기간에는 전면 조업을 중단해야 합니다.","keywords":["휴어","15일","조업중단"],"source":"2027 준수의무 가이드라인"},{"id":11,"category":"휴어","q":"2027년 휴어 점수는 어떻게 달라졌나요?","a":"휴어는 최대 25점입니다. 참여율은 전원 참여 5점, 80% 이상 100% 미만 3점입니다. 중단기간 점수는 금어기와 연속 설정인지 별도 설정인지에 따라 달라지며, 예를 들어 60일 이상은 각각 20점과 10점입니다.","keywords":["휴어점수","25점","금어기","연속"],"source":"2027 준수의무 가이드라인"},{"id":12,"category":"휴어","q":"금어기가 없는 어종의 휴어 점수는 어떻게 적용하나요?","a":"대상어종에 금어기가 없는 경우에는 '금어기와 별도' 기준을 적용합니다. TAC 참여어종이 여러 개이면 주어획종 1종에 적용합니다.","keywords":["금어기없음","별도","주어획종"],"source":"2027 준수의무 가이드라인"},{"id":13,"category":"전자어획보고","q":"2027년 전자어획보고는 어떤 앱을 사용하나요?","a":"해양수산부 '어획증명관리시스템 앱(Application)'을 활용하여 어획보고를 해야 합니다. 2027 가이드라인은 수협 조업정보알리미 앱은 사용할 수 없다고 안내합니다.","keywords":["어획증명관리시스템","앱","조업정보알리미"],"source":"2027 준수의무 가이드라인"},{"id":14,"category":"전자어획보고","q":"전자어획보고 참여 최소 기준과 배점은 어떻게 되나요?","a":"단체 구성원의 50% 이상이 참여해야 선택의무로 인정됩니다. 평가점수는 전원 20점, 90% 이상 18점, 80% 이상 16점, 70% 이상 14점, 60% 이상 12점, 50% 이상 10점입니다.","keywords":["전자어획보고","50%","20점"],"source":"2027 준수의무 가이드라인"},{"id":15,"category":"전자어획보고","q":"전자어획보고 이행 기간은 언제인가요?","a":"이행세부계획서상 어획보고 방법·기간은 2027년 2월 1일부터 9월 30일까지 입력 보고하는 것으로 안내되어 있습니다.","keywords":["전자어획보고","2월1일","9월30일"],"source":"2027 준수의무 가이드라인"},{"id":16,"category":"전자어획보고","q":"연안과 근해의 전자어획보고 인정 기준은 어떻게 다른가요?","a":"이행점검 기간 중 연안은 조업일마다, 근해는 1항차(출항~입항)마다 전자어획보고를 1회 이상 한 비율이 80% 이상이면 이행으로 처리합니다. 연안은 하루 여러 항차가 있어도 1회 보고하면 인정됩니다.","keywords":["연안","근해","1항차","80%"],"source":"2027 준수의무 가이드라인"},{"id":17,"category":"전자어획보고","q":"어획실적이 없으면 전자어획보고를 하지 않아도 되나요?","a":"아니요. 어획실적이 없는 경우에는 '어획물 없음'으로 보고하면 이행으로 처리됩니다.","keywords":["어획물없음","무어획"],"source":"2027 준수의무 가이드라인"},{"id":18,"category":"그밖의의무","q":"2027년 그 밖의 의무는 최대 몇 점인가요?","a":"최대 3개 항목까지 신청할 수 있고 최대 20점까지 반영됩니다. 여러 항목을 설정해도 선택의무 이행계획 수는 1개로 인정됩니다.","keywords":["그밖의의무","20점","3개"],"source":"2027 사업 시행지침·준수의무 가이드라인"},{"id":19,"category":"그밖의의무","q":"2027년 해양쓰레기 수거는 몇 점인가요?","a":"최대 10점입니다. 참여율은 전원 5점, 80% 이상 100% 미만 3점이고, 수거량은 근해 척당 3.5톤 이상 또는 연안 척당 200kg 이상일 때 5점입니다.","keywords":["해양쓰레기","10점","수거량"],"source":"2027 준수의무 가이드라인"},{"id":20,"category":"그밖의의무","q":"강화된 어구 제한과 체장·체중 제한은 몇 점인가요?","a":"각 항목은 최대 10점입니다. 단체 구성원 전원 참여 시 10점, 80% 이상 100% 미만 참여 시 8점입니다. 관련 법령보다 강화된 의무계획만 인정됩니다.","keywords":["어구제한","체장","체중","10점"],"source":"2027 준수의무 가이드라인"},{"id":21,"category":"감척","q":"2027년 감척 대상 어선은 직불금을 신청할 수 있나요?","a":"감척 대상으로 선정된 어선은 신청할 수 없습니다. 직불금 신청 이후 9월 30일 이전 감척대상으로 선정된 어선은 직불금 지급이 불가하고 이행점검 및 부적격 비율 모수에서 제외됩니다.","keywords":["감척","신청제한","9월30일"],"source":"2027 사업 시행지침"},{"id":22,"category":"직불금","q":"2027년 직불금 지급단가는 어떻게 되나요?","a":"2톤 이하 어선은 척당 150만원 정액입니다. 2톤 초과는 구간별로 10톤 이하 75만원/톤, 10~20톤 70만원/톤, 20톤 초과 65만원/톤을 적용해 합산합니다.","keywords":["직불금","150만원","75만원","70만원","65만원"],"source":"2027 사업 시행지침"},{"id":23,"category":"직불금","q":"개인과 법인의 직불금 상한은 얼마인가요?","a":"개인은 최대 90톤·6,000만원, 법인은 최대 140톤·9,250만원으로 한정합니다.","keywords":["상한","6000만원","9250만원","90톤","140톤"],"source":"2027 사업 시행지침"},{"id":24,"category":"직불금","q":"선단조업의 부속선 톤수는 어떻게 인정하나요?","a":"본선의 톤수를 기준으로 지급하고, 본선 외 부속선 등은 해당 어선 톤수 합의 10%를 총톤수에 추가 인정합니다. 개인·법인 지급상한톤수는 각각 90톤·140톤입니다.","keywords":["선단조업","부속선","10%"],"source":"2027 사업 시행지침"},{"id":25,"category":"감점","q":"2027년에 새로 안내된 중도포기 감점은 언제 적용되나요?","a":"2027 자료에 신설 내용으로 안내되어 있으나 적용은 2028년부터입니다. 불가피한 사유 없이 선택의무를 불이행한 전년도 선정 어업인은 1인당 3점 감점하고, 단체에 전년도 포기자가 4명 이상이면 최대 10점까지 감점합니다.","keywords":["중도포기","감점","2028","3점","10점"],"source":"2027 준수의무 가이드라인"},{"id":26,"category":"신청","q":"여러 지역의 신청인으로 단체를 구성하면 어디에 신청하나요?","a":"여러 지역의 신청인으로 구성된 단체는 단체사무소가 있는 대표지역으로 단체 및 개인 신청서류를 제출하여 신청·접수를 일원화합니다.","keywords":["여러지역","단체사무소","대표지역"],"source":"2027 준수의무 가이드라인"}];
